using System.Globalization;
using System.Text.Json;
using System.Text.RegularExpressions;
namespace CodexLight.Desktop;
internal sealed record ApplyReceipt(string Root,string Package,string Hash,int ParentPid,DateTime ParentStartUtc,string PackageId);
internal static class WorkerPolicy {
 internal static bool MayApply(bool canceled,bool committed,bool parentExited,TimeSpan elapsed){if(canceled)throw new OperationCanceledException("Apply canceled by native caller.");if(elapsed>TimeSpan.FromMinutes(5))throw new TimeoutException("Apply handoff expired.");if(parentExited&&!committed)throw new InvalidOperationException("Parent exited without commit.");return parentExited&&committed;}
 internal static string Canonical(string value){if(string.IsNullOrWhiteSpace(value)||!Regex.IsMatch(value,@"^[A-Za-z]:[\\/]")||value.Contains('\0'))throw new InvalidDataException("Local absolute path required.");return Path.GetFullPath(value).TrimEnd('\\','/');}
 internal static bool Within(string value,string root)=>Canonical(value).Equals(Canonical(root),StringComparison.OrdinalIgnoreCase)||Canonical(value).StartsWith(Canonical(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);
 internal static void Plain(string path){for(string? p=Canonical(path);p!=null;p=Path.GetDirectoryName(p))if((File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Reparse path refused.");}
 internal static string ReceiptPath(string[] args,string localData){if(args.Length!=2||args[0]!="--receipt")throw new InvalidDataException("Expected --receipt <path>.");var file=Canonical(args[1]);var dir=Path.Combine(localData,"CodexLight","Updates","Apply");if(!string.Equals(Path.GetDirectoryName(file),Canonical(dir),StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(Path.GetFileName(file),@"^[a-f0-9]{32}\.json$"))throw new InvalidDataException("Receipt outside fixed apply directory.");return file;}
 internal static ApplyReceipt Parse(string json){if(json.Length>16384)throw new InvalidDataException("Receipt too large.");using var doc=JsonDocument.Parse(json);var fields=new HashSet<string>(StringComparer.Ordinal);foreach(var p in doc.RootElement.EnumerateObject())if(!fields.Add(p.Name))throw new InvalidDataException("Duplicate receipt field.");if(!fields.SetEquals(new[]{"root","package","hash","parentPid","parentStartUtc","packageId"}))throw new InvalidDataException("Unexpected receipt fields.");var e=doc.RootElement;string S(string n)=>e.GetProperty(n).GetString()??throw new InvalidDataException("Null field.");var hash=S("hash");var id=S("packageId");var pid=e.GetProperty("parentPid").GetInt32();if(!Regex.IsMatch(hash,@"^[a-f0-9]{64}$")||id!=VelopackPackage.PackageId||pid<=0)throw new InvalidDataException("Invalid receipt identity.");var time=S("parentStartUtc");if(!DateTime.TryParseExact(time,"O",CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out var start)||start.Kind!=DateTimeKind.Utc)throw new InvalidDataException("UTC round-trip timestamp required.");return new(Canonical(S("root")),Canonical(S("package")),hash,pid,start,id);}
 internal static void CheckWorker(string ownExecutable,string root){if(Within(ownExecutable,root))throw new InvalidDataException("Worker must reside outside installed root.");Plain(ownExecutable);}
}

